<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Mirror News App Layout</title>
<style>
    :root {
        --bg-dark: #120e1a;
        --nav-red: #9e1b21;
        --nav-red-darker: #8b161c;
        --text-white: #ffffff;
        --accent-purple: #9b72a6; /* For 'ALAN CARR' tag */
        --accent-pink: #c78399;   /* For other tags and dividers */
        --bottom-nav-bg: #1a1a1a;
        --bottom-nav-active: #d15f79;
        --bottom-nav-inactive: #999999;
        --font-main: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    }

    * {
        box-sizing: border-box;
        margin: 0;
        padding: 0;
    }

    body {
        background-color: #000;
        display: flex;
        justify-content: center;
        font-family: var(--font-main);
        color: var(--text-white);
    }

    .mobile-container {
        width: 100%;
        max-width: 414px; /* Typical mobile width */
        background-color: var(--bg-dark);
        position: relative;
        overflow: hidden;
        display: flex;
        flex-direction: column;
        height: 100vh; /* Fill screen height for bottom nav positioning */
    }

    /* Status Bar */
    .status-bar {
        display: flex;
        justify-content: space-between;
        align-items: center;
        padding: 12px 20px;
        font-size: 14px;
        font-weight: 600;
        background-color: var(--bg-dark);
    }

    .status-icons {
        display: flex;
        gap: 5px;
        align-items: center;
    }

    /* Top Navigation */
    .top-nav {
        display: flex;
        background-color: var(--nav-red);
        height: 40px;
        align-items: center;
    }

    .nav-plus {
        width: 40px;
        height: 100%;
        display: flex;
        justify-content: center;
        align-items: center;
        background-color: var(--nav-red-darker);
    }

    .nav-plus-icon {
        background-color: white;
        color: var(--nav-red-darker);
        width: 16px;
        height: 16px;
        display: flex;
        justify-content: center;
        align-items: center;
        font-weight: bold;
        font-size: 14px;
        line-height: 1;
        border-radius: 2px;
    }

    .nav-links {
        display: flex;
        flex: 1;
        height: 100%;
    }

    .nav-item {
        flex: 1;
        display: flex;
        justify-content: center;
        align-items: center;
        font-size: 13px;
        font-weight: 700;
        text-transform: uppercase;
        border-right: 1px solid rgba(0,0,0,0.1);
    }

    .nav-item:last-child {
        border-right: none;
    }

    .nav-item.active {
        background-color: var(--nav-red-darker);
    }

    /* Scrollable Content Area */
    .content-area {
        flex: 1;
        overflow-y: auto;
        padding-bottom: 20px; /* Space before bottom nav */
    }

    /* Main Featured Article */
    .main-article {
        position: relative;
    }

    .main-image-container {
        position: relative;
        width: 100%;
        height: 240px;
        background-color: #333; /* Placeholder fallback */
    }

    .mirror-logo {
        position: absolute;
        top: 10px;
        left: 15px;
        background-color: #da131c;
        color: white;
        font-weight: 800;
        font-size: 28px;
        padding: 2px 8px;
        letter-spacing: -1px;
    }

    .main-text-content {
        padding: 15px;
    }

    .main-headline {
        font-size: 22px;
        font-weight: 700;
        line-height: 1.2;
        margin-bottom: 10px;
    }

    .tag {
        font-size: 11px;
        font-weight: 700;
        text-transform: uppercase;
        letter-spacing: 0.5px;
        display: flex;
        align-items: center;
    }

    .tag-main { color: var(--accent-purple); }
    .tag-secondary { color: var(--accent-pink); }

    /* Secondary Articles Grid */
    .news-grid {
        display: flex;
        padding: 0 15px;
        gap: 12px;
        align-items: stretch;
    }

    .grid-col {
        flex: 1;
        display: flex;
        flex-direction: column;
        width: calc(50% - 6px); /* Half minus half the gap */
    }

    .vertical-divider {
        width: 1px;
        background-color: var(--accent-pink);
        opacity: 0.3;
        margin-top: 5px;
    }

    .article-small {
        margin-bottom: 15px;
    }

    .article-small:last-child {
        margin-bottom: 0;
    }

    .small-headline {
        font-size: 15px;
        font-weight: 600;
        line-height: 1.3;
        margin-bottom: 8px;
    }

    .small-image-container {
        width: 100%;
        height: 100px;
        background-color: #444;
        margin-bottom: 10px;
        border-radius: 4px;
        overflow: hidden;
    }

    .horizontal-divider {
        height: 1px;
        background-color: var(--accent-pink);
        opacity: 0.3;
        margin: 12px 0;
    }

    /* Placeholders */
    .placeholder {
        display: flex;
        justify-content: center;
        align-items: center;
        background-color: #2a2a2a;
        color: #888;
        font-size: 12px;
        text-align: center;
        width: 100%;
        height: 100%;
        border: 1px dashed #555;
    }

    /* Bottom Navigation */
    .bottom-nav-container {
        background-color: var(--bottom-nav-bg);
        border-top: 1px solid #333;
        padding-bottom: env(safe-area-inset-bottom, 20px); /* For iPhone notch/bar */
    }

    .bottom-nav {
        display: flex;
        justify-content: space-around;
        align-items: center;
        height: 55px;
    }

    .nav-tab {
        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: center;
        flex: 1;
        color: var(--bottom-nav-inactive);
        font-size: 10px;
        gap: 4px;
    }

    .nav-tab.active {
        color: var(--bottom-nav-active);
    }

    .nav-icon-placeholder {
        width: 24px;
        height: 24px;
        border: 1.5px solid currentColor;
        border-radius: 4px;
        display: flex;
        align-items: center;
        justify-content: center;
        font-size: 14px;
    }

    .nav-tab:nth-child(2) .nav-icon-placeholder { border-radius: 50%; }
    .nav-tab:nth-child(3) .nav-icon-placeholder { border-bottom: none; border-radius: 4px 4px 0 0; }
    .nav-tab:nth-child(4) .nav-icon-placeholder { border-radius: 50%; }


    .home-indicator {
        width: 130px;
        height: 5px;
        background-color: white;
        border-radius: 3px;
        margin: 8px auto;
    }
</style>
</head>
<body>

<div class="mobile-container">

    <!-- Status Bar -->
    <div class="status-bar">
        <span>8:43</span>
        <span class="status-icons">
            <div style="width:16px; height:12px; background:white; mask:url('data:image/svg+xml;utf8,<svg ...></svg>')"></div>
            [Signal/Batt]
        </span>
    </div>

    <!-- Top Navigation -->
    <div class="top-nav">
        <div class="nav-plus">
            <div class="nav-plus-icon">+</div>
        </div>
        <div class="nav-links">
            <div class="nav-item active">TOP STORIES</div>
            <div class="nav-item">NEWS</div>
            <div class="nav-item">POLITICS</div>
        </div>
    </div>

    <!-- Scrollable Content -->
    <div class="content-area">

        <!-- Main Featured Article -->
        <div class="main-article">
            <div class="main-image-container">
                <div class="placeholder">[Photo: Close-up of man with black eye]</div>
                <div class="mirror-logo">Mirror</div>
            </div>
            <div class="main-text-content">
                <h1 class="main-headline">Alan Carr's husband says 'he never hit me' as he dismisses black eye pic rumours</h1>
                <div class="tag tag-main">ALAN CARR &#9654;</div>
            </div>
        </div>

        <!-- Secondary Articles Grid -->
        <div class="news-grid">

            <!-- Left Column -->
            <div class="grid-col left-col">
                <div class="article-small">
                    <div class="small-image-container">
                        <div class="placeholder">[Photo: Students celebrating results]</div>
                    </div>
                    <h2 class="small-headline">GCSE results hit record high after cancelled exams - with 30% getting top grades</h2>
                    <div class="tag tag-secondary">GCSES &#9654;</div>
                </div>

                <div class="horizontal-divider"></div>

                <div class="article-small">
                    <h2 class="small-headline">Rollercoaster comes off tracks at UK theme park as emergency crews...</h2>
                </div>
            </div>

            <!-- Vertical Separator -->
            <div class="vertical-divider"></div>

            <!-- Right Column -->
            <div class="grid-col right-col">
                <div class="article-small">
                    <h2 class="small-headline">Woman, 32, killed in horror bus crash described as 'kind and thoughtful soul'</h2>
                    <div class="tag tag-secondary">TRANSPORT FOR LON...</div>
                </div>

                <div class="horizontal-divider"></div>

                <div class="article-small">
                    <h2 class="small-headline">Brit spy suspect is 'stocky bald man with right-wing views who drives a Fiesta'</h2>
                    <div class="tag tag-secondary">MILITARY INTELLIGEN...</div>
                </div>

                <div class="horizontal-divider"></div>

                <div class="article-small">
                    <div class="small-image-container">
                        <div class="placeholder">[Photo: Two people walking outside building]</div>
                    </div>
                </div>
            </div>

        </div> <!-- End Grid -->
    </div> <!-- End Content Area -->

    <!-- Bottom Navigation -->
    <div class="bottom-nav-container">
        <div class="bottom-nav">
            <div class="nav-tab active">
                <div class="nav-icon-placeholder">&#9776;</div>
                <span>My News</span>
            </div>
            <div class="nav-tab">
                <div class="nav-icon-placeholder">&#9906;</div>
                <span>Discover</span>
            </div>
            <div class="nav-tab">
                <div class="nav-icon-placeholder">&#9733;</div>
                <span>Bookmarks</span>
            </div>
            <div class="nav-tab">
                <div class="nav-icon-placeholder">&#9786;</div>
                <span>My Account</span>
            </div>
        </div>
        <div class="home-indicator"></div>
    </div>

</div>

</body>
</html>
